# MAGIC <div class="dbx">
# MAGIC <div class="sec-head"><span class="sec-num">07</span><span class="sec-icon">🚀</span><h2>CI/CD with GitHub Actions</h2></div><div class="code"><div class="code-bar"><i></i><i></i><i></i><span class="lang">YAML</span><button class="copy" type="button">copy</button></div><pre><span style="color: #8B949E; font-style: italic"># .github/workflows/deploy.yml (simplified)</span>
# MAGIC <span style="color: #7EE787">on</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #7EE787">pull_request</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #7EE787">push</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">branches</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #E6EDF3">[</span><span style="color: #79C0FF">main</span><span style="color: #E6EDF3">]</span>
# MAGIC <span style="color: #7EE787">jobs</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">  </span><span style="color: #7EE787">deploy</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">runs-on</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">ubuntu-latest</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">env</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #7EE787">DATABRICKS_HOST</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">&#36;{{ secrets.DATABRICKS_HOST }}</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #7EE787">DATABRICKS_CLIENT_ID</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">&#36;{{ secrets.SP_CLIENT_ID }}</span><span style="color: #6E7681">          </span><span style="color: #8B949E; font-style: italic"># service principal (OAuth M2M)</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #7EE787">DATABRICKS_CLIENT_SECRET</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">&#36;{{ secrets.SP_CLIENT_SECRET }}</span>
# MAGIC <span style="color: #6E7681">    </span><span style="color: #7EE787">steps</span><span style="color: #E6EDF3">:</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">uses</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">actions/checkout@v4</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">uses</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">databricks/setup-cli@main</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">run</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">pip install pytest pyspark &amp;&amp; pytest tests/</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">run</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">databricks bundle validate -t staging</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">run</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">databricks bundle deploy -t staging &amp;&amp; databricks bundle run -t staging integration_tests</span>
# MAGIC <span style="color: #6E7681">      </span><span style="color: #E6EDF3">-</span><span style="color: #6E7681"> </span><span style="color: #7EE787">if</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">github.ref == 'refs/heads/main'</span>
# MAGIC <span style="color: #6E7681">        </span><span style="color: #7EE787">run</span><span style="color: #E6EDF3">:</span><span style="color: #6E7681"> </span><span style="color: #A5D6FF">databricks bundle deploy -t prod</span></pre></div>
# MAGIC <ul>
# MAGIC <li><strong>Pull request:</strong> unit tests, <code>validate</code>, deploy to <strong>staging</strong>, integration tests.</li>
# MAGIC <li><strong>Merge to main:</strong> deploy the <strong>same commit</strong> to <strong>prod</strong>.</li>
# MAGIC <li>Authenticate CI as a <strong>service principal</strong> with OAuth, or with workload identity federation. Don't use a person's PAT.</li>
# MAGIC </ul>
# MAGIC </div>

